#!/usr/bin/env bash
set -Eeuo pipefail
APP_ROOT="/opt/veloraos"
SERVICE="veloraos"
PORT="8100"
PAYLOAD_SHA256="1ad0e3b252796b48ea385b4bc9d192cac4ab4901f02f2cc58c55ced90a5824a9"
[[ "${1:-}" == "--non-interactive" || "${VELORAOS_NONINTERACTIVE:-0}" == "1" ]] || { echo "Use --non-interactive." >&2; exit 1; }
[[ ${EUID:-$(id -u)} -eq 0 ]] || { echo "Run as root." >&2; exit 1; }
TMP="$(mktemp -d /tmp/veloraos-1.10.43-ui.XXXXXX)"
BACKUP="/opt/veloraos-update-backups/pre-1.10.43-ui-$(date +%Y%m%d-%H%M%S)"
SUCCESS=0
cleanup(){ rm -rf "$TMP" 2>/dev/null || true; }
rollback(){
  code=$?
  trap - EXIT INT TERM
  if [[ "$SUCCESS" != "1" && -d "$BACKUP/app/static" ]]; then
    cp -a "$BACKUP/app/static/." "$APP_ROOT/app/static/"
    systemctl restart "$SERVICE" 2>/dev/null || true
  fi
  cleanup
  exit "$code"
}
trap rollback EXIT INT TERM
mkdir -p "$BACKUP/app/static"
cp -a "$APP_ROOT/app/static/." "$BACKUP/app/static/"
awk 'found{print} $0=="__VELORAOS_11043_UI_PAYLOAD__"{found=1}' "$0" | base64 -d > "$TMP/payload.tgz"
printf '%s  %s\n' "$PAYLOAD_SHA256" "$TMP/payload.tgz" | sha256sum -c - >/dev/null
mkdir -p "$TMP/stage"
tar -xzf "$TMP/payload.tgz" -C "$TMP/stage"
node --check "$TMP/stage/app/static/app.js" >/dev/null 2>&1 || true
grep -Fq 'addMemory:addMemory' "$TMP/stage/app/static/app.js"
grep -Fq 'chatDrafts:{}' "$TMP/stage/app/static/app.js"
cp -a "$TMP/stage/app/static/." "$APP_ROOT/app/static/"
systemctl restart "$SERVICE"
sleep 2
curl -fsS "http://127.0.0.1:$PORT/api/health" >/dev/null
SUCCESS=1
cleanup
trap - EXIT INT TERM
echo "[VeloraOS 1.10.43] Memory UI and chat draft hotfix complete."
